    for i in range(len(ciphertext)):
        row = alphabet[(ord(key[i % length]) - ord('a')) % 26]
        row_offset = 0
        for char in ciphertext[i]:
            if char in alphabet:
                shift = alphabet.index(row[row_offset])
                if char.islower():
                    result += alphabet[(ord(char) - ord('a') - shift) % 26].upper()
